(function executeRule(current, previous /*null when async*/ ) {
        // MSSCUSTODY-6121
        var schemecode = [];
        gr = new GlideRecord('x_hsb11_mss_trus_0_mss_trustees_routing_table_for_case_task');
        gr.addEncodedQuery('active=true^assignment_groupDYNAMICd6435e965f510100a9ad2572f2b47744^ORu_caseassignmentgroupDYNAMICd6435e965f510100a9ad2572f2b47744');
        gr.query();
        while (gr.next()) {
            schemecode.push(gr.getValue('schema_code'));
        }
        var arrayUtil = new global.ArrayUtil();
        var casequery = 'scheme_codeIN' + arrayUtil.unique(schemecode);

    current.addEncodedQuery(casequery);
	//current.addEncodedQuery(opened_byDYNAMIC90d1921e5f510100a9ad2572f2b477fe);

})(current, previous);
